1	package indexroom
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"slices"
10		"strconv"
11		"unicode/utf8"
12	)
13	
14	// ErrInvalidSnapshot marks a rejected snapshot document: malformed or
15	// truncated JSON, trailing data after the object, an unknown version,
16	// missing, mistyped, unknown, or duplicated fields, a null where version,
17	// tip, height, hash, parent, or a transaction identifier is required,
18	// heights that do not ascend consecutively from 1, an empty or duplicated
19	// hash, a broken parent link, a version-2 timestamp that is missing or
20	// neither null nor a non-negative integer, a hash, parent, or transaction
21	// identifier whose JSON string carries invalid UTF-8 bytes or unpaired or
22	// misordered Unicode surrogate escapes, or a tip that disagrees with the
23	// block list. A rejected restore never changes the index.
24	var ErrInvalidSnapshot = errors.New("indexroom: invalid snapshot")
25	
26	const (
27		// snapshotVersion1 is the timestamp-less layout. It stays readable
28		// indefinitely; its blocks restore with missing timestamps.
29		snapshotVersion1 = 1
30		// snapshotVersion2 adds a required timestamp field to every block:
31		// either a non-negative Unix-seconds integer or null for missing time.
32		snapshotVersion2 = 2
33	)
34	
35	// snapshotDoc is the wire form of an exported main chain. Both layout
36	// versions share one shape: Version selects whether every block carries its
37	// Timestamp field.
38	type snapshotDoc struct {
39		Version int64           `json:"version"`
40		Tip     int64           `json:"tip"`
41		Blocks  []snapshotBlock `json:"blocks"`
42	}
43	
44	// snapshotBlock is the wire form of one block, shared by both versions.
45	// Height, hash, parent, and the transaction list follow the same rules in
46	// either layout. The timestamp is version 2 only and carried as a raw
47	// literal: nil is omitted altogether (version 1), "null" marks a missing
48	// time, and integer bytes render the Unix-seconds value (version 2). It
49	// stays the final field in every layout.
50	type snapshotBlock struct {
51		Height    int64           `json:"height"`
52		Hash      string          `json:"hash"`
53		Parent    string          `json:"parent"`
54		Txs       []string        `json:"txs"`
55		Timestamp json.RawMessage `json:"timestamp,omitempty"`
56	}
57	
58	// Export writes the current main chain to w as a JSON snapshot: a single
59	// object with version, tip, and the blocks ordered by ascending height, each
60	// carrying its transactions in order. The same main chain always produces
61	// the same bytes, regardless of the reorg, restore, or query history that
62	// led to it. Only blocks in effect at export time appear; nothing the index
63	// once held and later dropped is included.
64	//
65	// A chain whose blocks all lack timestamps keeps the original version-1
66	// layout, byte for byte. As soon as any block carries a timestamp the
67	// document is version 2 and every block includes a timestamp field: a
68	// non-negative integer or null for a missing timestamp.
69	//
70	// Export observes one complete chain state and never modifies the index.
71	// The chain is copied under the lock and serialized afterwards, so queries
72	// and appends proceed while the stream is still being written. A write
73	// failure is reported and leaves the index untouched.
74	func (index *Index) Export(w io.Writer) error {
75		doc := index.snapshotChain()
76		raw, err := json.Marshal(doc)
77		if err != nil {
78			panic(err) // snapshot docs only contain marshalable fields
79		}
80		n, err := w.Write(raw)
81		if err != nil {
82			return fmt.Errorf("indexroom: export snapshot: %w", err)
83		}
84		if n != len(raw) {
85			return fmt.Errorf("indexroom: export snapshot: %w", io.ErrShortWrite)
86		}
87		return nil
88	}
89	
90	// snapshotChain copies the current main chain into the export wire
91	// form: blocks by ascending height, each with its transactions copied in
92	// original order. This is the single place that turns stored blocks into the
93	// shared document fields, so both layout versions keep identical rules for
94	// height, hash, parent, and the transaction list; the only version-dependent
95	// field is the timestamp literal.
96	//
97	// The version is selected from the same chain copy. Any block carrying a
98	// timestamp — even a zero — makes the document version 2, after which every
99	// block gets a timestamp field, null where its time is missing; a chain
100	// whose blocks all lack times stays version 1 with no timestamp field.
101	func (index *Index) snapshotChain() snapshotDoc {
102		index.mu.Lock()
103		defer index.mu.Unlock()
104		version := int64(snapshotVersion1)
105		for height := int64(1); height <= index.Tip; height++ {
106			if index.Blocks[height].Time != nil {
107				version = snapshotVersion2
108				break
109			}
110		}
111		doc := snapshotDoc{
112			Version: version,
113			Tip:     index.Tip,
114			Blocks:  make([]snapshotBlock, 0, int(index.Tip)),
115		}
116		for height := int64(1); height <= index.Tip; height++ {
117			block := index.Blocks[height]
118			txs := make([]string, len(block.Txs))
119			copy(txs, block.Txs)
120			entry := snapshotBlock{
121				Height: block.Height,
122				Hash:   block.Hash,
123				Parent: block.Parent,
124				Txs:    txs,
125			}
126			if version == snapshotVersion2 {
127				entry.Timestamp = snapshotTimestampLiteral(block.Time)
128			}
129			doc.Blocks = append(doc.Blocks, entry)
130		}
131		return doc
132	}
133	
134	// snapshotMissingTimestamp is the raw JSON literal written for a block whose
135	// time is missing in a version-2 document.
136	var snapshotMissingTimestamp = json.RawMessage("null")
137	
138	// snapshotTimestampLiteral renders a stored block time as its version-2
139	// timestamp literal: null for a missing time, otherwise its non-negative
140	// Unix-seconds value as a bare integer. Stored times are guaranteed
141	// non-negative by Append, Reorg, and Restore validation.
142	func snapshotTimestampLiteral(time *int64) json.RawMessage {
143		if time == nil {
144			return snapshotMissingTimestamp
145		}
146		return json.RawMessage(strconv.AppendInt(nil, *time, 10))
147	}
148	
149	// Restore replaces the whole main chain with the snapshot read from r. The
150	// input must be exactly one snapshot object, optionally followed by
151	// whitespace; every block is validated — including heights ascending from 1,
152	// non-empty unique hashes, and parent linkage — before anything is applied.
153	// The first block's parent is exempt from linkage: it names the chain start
154	// and need not be indexed.
155	//
156	// The replacement takes effect as one complete operation: on success the
157	// index holds exactly the snapshot chain with no leftover heights or hashes,
158	// and on any failure — a read error or an invalid block discovered at the
159	// very end — the current chain and every previously issued cursor remain as
160	// they were. The stream is consumed and validated before the lock is taken,
161	// so the index stays queryable and appendable while the restore is reading.
162	//
163	// After a successful restore, cursors issued earlier by this same index keep
164	// working wherever the pinned range still matches and the tip still covers
165	// it; otherwise continuations fail with ErrQueryChanged as usual.
166	func (index *Index) Restore(r io.Reader) error {
167		tip, blocks, err := parseSnapshot(r)
168		if err != nil {
169			return err
170		}
171		stored := make(map[int64]Block, len(blocks))
172		byHash := make(map[string]int64, len(blocks))
173		for _, block := range blocks {
174			stored[block.Height] = block
175			byHash[block.Hash] = block.Height
176		}
177		index.mu.Lock()
178		index.Blocks = stored
179		index.ByHash = byHash
180		index.Tip = tip
181		index.mu.Unlock()
182		return nil
183	}
184	
185	// parseSnapshot reads and fully validates one snapshot document. It returns
186	// the tip height and the validated blocks in ascending height order.
187	func parseSnapshot(r io.Reader) (int64, []Block, error) {
188		dec := json.NewDecoder(r)
189		tok, err := dec.Token()
190		if err != nil {
191			return 0, nil, classifySnapshotErr(err)
192		}
193		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
194			return 0, nil, invalidSnapshot("snapshot must be a single JSON object")
195		}
196	
197		// Top-level fields are captured raw so blocks can be parsed with the
198		// strict schema matching the declared version, whatever the field order,
199		// and so null can be told apart from a zero value.
200		var (
201			rawVersion, rawTip   json.RawMessage
202			rawBlocks            json.RawMessage
203			haveVersion, haveTip bool
204			haveBlocks           bool
205			seen                 = map[string]bool{}
206		)
207		for dec.More() {
208			key, err := snapshotKey(dec)
209			if err != nil {
210				return 0, nil, err
211			}
212			if seen[key] {
213				return 0, nil, invalidSnapshot("duplicate field %q", key)
214			}
215			seen[key] = true
216			switch key {
217			case "version":
218				if err := dec.Decode(&rawVersion); err != nil {
219					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
220				}
221				haveVersion = true
222			case "tip":
223				if err := dec.Decode(&rawTip); err != nil {
224					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
225				}
226				haveTip = true
227			case "blocks":
228				if err := dec.Decode(&rawBlocks); err != nil {
229					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
230				}
231				haveBlocks = true
232			default:
233				return 0, nil, invalidSnapshot("unknown field %q", key)
234			}
235		}
236		if _, err := dec.Token(); err != nil { // closing '}'
237			return 0, nil, classifySnapshotErr(err)
238		}
239		// Only whitespace may follow the snapshot object.
240		if _, err := dec.Token(); err != io.EOF {
241			if err == nil {
242				return 0, nil, invalidSnapshot("trailing data after the snapshot object")
243			}
244			return 0, nil, classifySnapshotErr(err)
245		}
246	
247		if !haveVersion {
248			return 0, nil, invalidSnapshot("missing field %q", "version")
249		}
250		if !haveTip {
251			return 0, nil, invalidSnapshot("missing field %q", "tip")
252		}
253		if !haveBlocks {
254			return 0, nil, invalidSnapshot("missing field %q", "blocks")
255		}
256		version, err := snapshotInt64(rawVersion, "version")
257		if err != nil {
258			return 0, nil, err
259		}
260		tip, err := snapshotInt64(rawTip, "tip")
261		if err != nil {
262			return 0, nil, err
263		}
264		if version != snapshotVersion1 && version != snapshotVersion2 {
265			return 0, nil, invalidSnapshot("unsupported version %d", version)
266		}
267	
268		blockDec := json.NewDecoder(bytes.NewReader(rawBlocks))
269		blocks, err := parseSnapshotBlocks(blockDec, version)
270		if err != nil {
271			return 0, nil, err
272		}
273		if _, err := blockDec.Token(); err != io.EOF {
274			if err == nil {
275				return 0, nil, invalidSnapshot("trailing data after the blocks array")
276			}
277			return 0, nil, classifySnapshotErr(err)
278		}
279	
280		lastHeight := int64(0)
281		if len(blocks) > 0 {
282			lastHeight = blocks[len(blocks)-1].Height
283		}
284		if tip != lastHeight {
285			return 0, nil, invalidSnapshot("tip %d does not match the last block height %d", tip, lastHeight)
286		}
287		return tip, blocks, nil
288	}
289	
290	// parseSnapshotBlocks reads the blocks array value, validating heights,
291	// hashes, parent links, and (for version 2) timestamps as it goes.
292	func parseSnapshotBlocks(dec *json.Decoder, version int64) ([]Block, error) {
293		tok, err := dec.Token()
294		if err != nil {
295			return nil, classifySnapshotErr(err)
296		}
297		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
298			return nil, invalidSnapshot("field %q must be an array", "blocks")
299		}
300		blocks := []Block{}
301		seenHash := map[string]bool{}
302		for dec.More() {
303			var block Block
304			if version == snapshotVersion2 {
305				block, err = parseSnapshotBlockV2(dec)
306			} else {
307				block, err = parseSnapshotBlock(dec)
308			}
309			if err != nil {
310				return nil, err
311			}
312			want := int64(len(blocks) + 1)
313			if block.Height != want {
314				return nil, invalidSnapshot("block height %d out of order, expected %d", block.Height, want)
315			}
316			if block.Hash == "" {
317				return nil, invalidSnapshot("block at height %d has an empty hash", block.Height)
318			}
319			if seenHash[block.Hash] {
320				return nil, invalidSnapshot("duplicate hash %q", block.Hash)
321			}
322			seenHash[block.Hash] = true
323			// The first block's parent names the chain start and is exempt from
324			// linkage; every later block must point at its predecessor.
325			if len(blocks) > 0 && block.Parent != blocks[len(blocks)-1].Hash {
326				return nil, invalidSnapshot("block at height %d does not link to its parent", block.Height)
327			}
328			blocks = append(blocks, block)
329		}
330		if _, err := dec.Token(); err != nil { // closing ']'
331			return nil, classifySnapshotErr(err)
332		}
333		return blocks, nil
334	}
335	
336	// parseSnapshotBlock reads one version-1 block object, requiring exactly the
337	// fields height, hash, parent, and txs.
338	func parseSnapshotBlock(dec *json.Decoder) (Block, error) {
339		var block Block
340		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs")
341		if err != nil {
342			return block, err
343		}
344		return finishSnapshotBlock(fields)
345	}
346	
347	// parseSnapshotBlockV2 reads one version-2 block object, requiring exactly
348	// the fields height, hash, parent, txs, and timestamp. Timestamp must be
349	// null or a non-negative integer; the block returns a nil time for null.
350	func parseSnapshotBlockV2(dec *json.Decoder) (Block, error) {
351		var block Block
352		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs", "timestamp")
353		if err != nil {
354			return block, err
355		}
356		if _, ok := fields["timestamp"]; !ok {
357			return block, invalidSnapshot("block is missing field %q", "timestamp")
358		}
359		block, err = finishSnapshotBlock(fields)
360		if err != nil {
361			return block, err
362		}
363		t, err := parseSnapshotTimestamp(fields["timestamp"])
364		if err != nil {
365			return Block{}, err
366		}
367		block.Time = t
368		return block, nil
369	}
370	
371	// readSnapshotBlockObject reads one block object and captures each known
372	// field's raw value. Fields are decoded only after the whole object is read,
373	// so a null can be rejected per field and a txs element error can name the
374	// block's height whatever order the fields arrive in.
375	func readSnapshotBlockObject(dec *json.Decoder, known ...string) (map[string]json.RawMessage, error) {
376		tok, err := dec.Token()
377		if err != nil {
378			return nil, classifySnapshotErr(err)
379		}
380		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
381			return nil, invalidSnapshot("block must be a JSON object")
382		}
383		fields := map[string]json.RawMessage{}
384		for dec.More() {
385			key, err := snapshotKey(dec)
386			if err != nil {
387				return nil, err
388			}
389			if _, dup := fields[key]; dup {
390				return nil, invalidSnapshot("duplicate block field %q", key)
391			}
392			if !slices.Contains(known, key) {
393				return nil, invalidSnapshot("unknown block field %q", key)
394			}
395			var raw json.RawMessage
396			if err := dec.Decode(&raw); err != nil {
397				return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
398			}
399			fields[key] = raw
400		}
401		if _, err := dec.Token(); err != nil { // closing '}'
402			return nil, classifySnapshotErr(err)
403		}
404		return fields, nil
405	}
406	
407	// finishSnapshotBlock decodes the shared block fields from their raw values,
408	// requiring height, hash, parent, and txs and rejecting null for each.
409	func finishSnapshotBlock(fields map[string]json.RawMessage) (Block, error) {
410		var block Block
411		for _, field := range []string{"height", "hash", "parent", "txs"} {
412			if _, ok := fields[field]; !ok {
413				return block, invalidSnapshot("block is missing field %q", field)
414			}
415		}
416		var err error
417		if block.Height, err = snapshotInt64(fields["height"], "height"); err != nil {
418			return block, err
419		}
420		if block.Hash, err = snapshotString(fields["hash"], "hash", block.Height); err != nil {
421			return block, err
422		}
423		if block.Parent, err = snapshotString(fields["parent"], "parent", block.Height); err != nil {
424			return block, err
425		}
426		txs, err := parseSnapshotTxs(json.NewDecoder(bytes.NewReader(fields["txs"])), block.Height)
427		if err != nil {
428			return block, err
429		}
430		block.Txs = txs
431		return block, nil
432	}
433	
434	// snapshotInt64 decodes one required integer field, rejecting null rather
435	// than letting it pass as zero.
436	func snapshotInt64(raw json.RawMessage, field string) (int64, error) {
437		if isSnapshotNull(raw) {
438			return 0, invalidSnapshot("field %q must not be null", field)
439		}
440		var v int64
441		if err := json.Unmarshal(raw, &v); err != nil {
442			return 0, classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
443		}
444		return v, nil
445	}
446	
447	// snapshotString decodes one required string field, rejecting null rather
448	// than letting it pass as the empty string. The raw literal is also checked
449	// for invalid UTF-8 bytes and unpaired or misordered \uXXXX surrogate
450	// escapes, which the decoder would otherwise silently rewrite to U+FFFD;
451	// height identifies the block the field belongs to in the error.
452	func snapshotString(raw json.RawMessage, field string, height int64) (string, error) {
453		if isSnapshotNull(raw) {
454			return "", invalidSnapshot("field %q must not be null", field)
455		}
456		var s string
457		if err := json.Unmarshal(raw, &s); err != nil {
458			return "", classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
459		}
460		if !validSnapshotString(raw) {
461			return "", invalidSnapshot("block at height %d: field %q has invalid UTF-8 or unpaired surrogate escapes", height, field)
462		}
463		return s, nil
464	}
465	
466	// isSnapshotNull reports whether a raw field value is the JSON null literal.
467	func isSnapshotNull(raw json.RawMessage) bool {
468		return string(raw) == "null"
469	}
470	
471	// validSnapshotString reports whether raw is a JSON string literal whose
472	// content is valid UTF-8 and whose \uXXXX escapes contain no unpaired or
473	// misordered surrogates. The JSON decoder accepts both defects silently,
474	// rewriting the bad parts to U+FFFD, which could merge distinct identifiers;
475	// the raw bytes are checked here before the decoded value is trusted. A
476	// genuine U+FFFD — written literally or as a \ufffd escape — is valid
477	// UTF-8 and passes.
478	func validSnapshotString(raw json.RawMessage) bool {
479		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
480			return false
481		}
482		body := raw[1 : len(raw)-1]
483		for i := 0; i < len(body); {
484			b := body[i]
485			switch {
486			case b == '\\':
487				if i+1 >= len(body) {
488					return false
489				}
490				if body[i+1] != 'u' {
491					i += 2 // \", \\, \/, \b, \f, \n, \r, \t
492					continue
493				}
494				code, ok := snapshotHex4(body, i+2)
495				if !ok {
496					return false
497				}
498				i += 6
499				switch {
500				case code >= 0xD800 && code <= 0xDBFF:
501					// A high surrogate is only valid as the first half of a
502					// pair; the low half must follow immediately as an escape.
503					if i+6 > len(body) || body[i] != '\\' || body[i+1] != 'u' {
504						return false
505					}
506					low, ok := snapshotHex4(body, i+2)
507					if !ok || low < 0xDC00 || low > 0xDFFF {
508						return false
509					}
510					i += 6
511				case code >= 0xDC00 && code <= 0xDFFF:
512					return false // a low surrogate cannot appear on its own
513				}
514			case b < utf8.RuneSelf:
515				i++
516			default:
517				// DecodeRune returns RuneError with size 1 for invalid
518				// encoding; a genuine U+FFFD decodes with size 3.
519				r, size := utf8.DecodeRune(body[i:])
520				if r == utf8.RuneError && size <= 1 {
521					return false
522				}
523				i += size
524			}
525		}
526		return true
527	}
528	
529	// snapshotHex4 reads four hexadecimal digits starting at b[i].
530	func snapshotHex4(b []byte, i int) (rune, bool) {
531		if i+4 > len(b) {
532			return 0, false
533		}
534		var v rune
535		for _, c := range b[i : i+4] {
536			var d byte
537			switch {
538			case '0' <= c && c <= '9':
539				d = c - '0'
540			case 'a' <= c && c <= 'f':
541				d = c - 'a' + 10
542			case 'A' <= c && c <= 'F':
543				d = c - 'A' + 10
544			default:
545				return 0, false
546			}
547			v = v*16 + rune(d)
548		}
549		return v, true
550	}
551	
552	// parseSnapshotTimestamp reads one timestamp value: null for a missing
553	// timestamp, or a non-negative integer. Zero is stored as a real timestamp,
554	// distinct from null.
555	func parseSnapshotTimestamp(raw json.RawMessage) (*int64, error) {
556		var t *int64
557		if err := json.Unmarshal(raw, &t); err != nil {
558			return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", "timestamp", err))
559		}
560		if t != nil && *t < 0 {
561			return nil, invalidSnapshot("timestamp must not be negative")
562		}
563		return t, nil
564	}
565	
566	// parseSnapshotTxs reads one txs array, preserving duplicates and empty
567	// identifiers exactly as written. A null element is rejected, naming the
568	// block's height and the element's zero-based position, and so is an
569	// element whose raw string carries invalid UTF-8 bytes or unpaired or
570	// misordered surrogate escapes.
571	func parseSnapshotTxs(dec *json.Decoder, height int64) ([]string, error) {
572		tok, err := dec.Token()
573		if err != nil {
574			return nil, classifySnapshotErr(err)
575		}
576		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
577			return nil, invalidSnapshot("field %q must be an array of strings", "txs")
578		}
579		txs := []string{}
580		for dec.More() {
581			var raw json.RawMessage
582			if err := dec.Decode(&raw); err != nil {
583				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
584			}
585			if isSnapshotNull(raw) {
586				return nil, invalidSnapshot("block at height %d: txs element %d must not be null", height, len(txs))
587			}
588			var tx string
589			if err := json.Unmarshal(raw, &tx); err != nil {
590				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
591			}
592			if !validSnapshotString(raw) {
593				return nil, invalidSnapshot("block at height %d: field %q element %d has invalid UTF-8 or unpaired surrogate escapes", height, "txs", len(txs))
594			}
595			txs = append(txs, tx)
596		}
597		if _, err := dec.Token(); err != nil { // closing ']'
598			return nil, classifySnapshotErr(err)
599		}
600		return txs, nil
601	}
602	
603	// snapshotKey reads the next object key.
604	func snapshotKey(dec *json.Decoder) (string, error) {
605		tok, err := dec.Token()
606		if err != nil {
607			return "", classifySnapshotErr(err)
608		}
609		key, ok := tok.(string)
610		if !ok {
611			return "", invalidSnapshot("object key must be a string")
612		}
613		return key, nil
614	}
615	
616	// invalidSnapshot builds an ErrInvalidSnapshot error with a specific reason.
617	func invalidSnapshot(format string, args ...any) error {
618		return fmt.Errorf("%w: %s", ErrInvalidSnapshot, fmt.Sprintf(format, args...))
619	}
620	
621	// classifySnapshotErr maps decoder failures onto the snapshot error model:
622	// malformed JSON, wrong value types, and truncation are snapshot errors,
623	// while anything else is an underlying read failure reported as-is.
624	func classifySnapshotErr(err error) error {
625		var syntaxErr *json.SyntaxError
626		var typeErr *json.UnmarshalTypeError
627		switch {
628		case errors.As(err, &syntaxErr), errors.As(err, &typeErr):
629			return fmt.Errorf("%w: %v", ErrInvalidSnapshot, err)
630		case errors.Is(err, io.EOF), errors.Is(err, io.ErrUnexpectedEOF):
631			return fmt.Errorf("%w: unexpected end of input", ErrInvalidSnapshot)
632		default:
633			return fmt.Errorf("indexroom: read snapshot: %w", err)
634		}
635	}
636

